('15', 'Investiture Ceremony & Student Council', 'Time-honoured tradition selecting Head Boy, Head Girl and student leaders.', 'assets/images/investiture-ceremony.jpeg', 'Events', '15', '1', '2026-10-24 10:55:55'),
