('18', 'Outdoor 3D Maths Zone', 'Experiential geometry park featuring large 3D models with Euler\'s formulas and surface area properties.', 'assets/images/maths-zone-3d.jpeg', 'Campus', '18', '1', '2026-10-24 10:55:55'),
