INSERT INTO `newsletter_subscribers` VALUES
('1', 'parent.mgm@example.com', '2026-10-21 23:28:40');
INSERT INTO `notices` VALUES
('1', 'Admissions Open for Academic Year 2025–2026: Pre-KG to Grade XI', 'admissions-open-2025-2026', 'Admission', 'danger', '2026-10-15', 'October 15, 2026', 'Admissions are officially open for Pre-Primary (Pre-KG, LKG, UKG), Primary, Middle, Secondary, and Senior Secondary (Science, Commerce & Humanities) streams for the 2025–2026 academic year. Download prospectus or visit campus desk.', 'MGM Model School Ayiroor, Varkala announces the commencement of admission registrations for the upcoming academic session 2025–2026. Offering CBSE affiliated comprehensive curriculum with smart classrooms, state-of-the-art AI Innovation Centre, STEM robotics, semi-olympic swimming pool, and dedicated school bus transportation across Varkala and surrounding areas. Parents can collect registration kits from the administrative office between 8:30 AM and 3:30 PM on weekdays.', 'assets/images/Untitled-design-4.png', NULL, '1', '1', '1', '2026-10-24 15:15:06', '2026-10-24 15:15:06'),
('2', 'CBSE Board Examination Merit Honors: Outstanding 100% Pass Results', 'cbse-board-merit-honors', 'Academic', 'success', '2026-09-28', 'September 28, 2026', 'Hearty congratulations to our Grade X & XII CBSE Board exam achievers who secured distinctions and top percentiles, continuing MGM Model School\'s tradition of 100% pass excellence.', 'MGM Model School rejoices in the remarkable academic accomplishment of its students in the recent CBSE Class X and Class XII Board Examinations. With a stellar 100% pass rate, our toppers achieved A1 grades across all core subjects. The Management, Principal, and Faculty extend heartfelt congratulations to the students and their proud parents for this prestigious milestone.', 'assets/images/Untitled-design-15.jpg', NULL, '1', '1', '2', '2026-10-24 15:15:06', '2026-10-24 15:15:06'),
('3', 'Prestigious Rajyapuraskar (Governor\'s Award) Bestowed on Scouts & Guides Cadets', 'rajyapuraskar-governors-award-felicitation', 'Achievement', 'primary', '2026-09-10', 'September 10, 2026', 'MGM Model School Hindustan Scouts and Guides cadets have been conferred the prestigious Rajyapuraskar (Governor\'s Award) by the Hon\'ble Governor of Kerala for leadership and public service.', 'In a proud moment of glory, cadets of MGM Model School\'s Hindustan Scouts & Guides troop have been awarded the prestigious Rajyapuraskar Certificate by the Hon\'ble Governor of Kerala. This highest state-level recognition commends their exemplary dedication, community service projects, survival camps, and leadership drills.', 'assets/images/rajyapuraskar-2024.png', NULL, '1', '1', '3', '2026-10-24 15:15:06', '2026-10-24 15:15:06'),
('4', 'State-of-the-Art Innovation Centre & AI Robotics Hub Inaugurated', 'innovation-centre-ai-robotics-inauguration', 'Event', 'info', '2026-08-20', 'August 20, 2026', 'Inauguration of OMNIS Educational Humanoid Robot, NOVA KG AI Hub, and 3D Rapid Prototyping Laboratory by Hon\'ble Governor of Kerala, Shri Arif Mohammed Khan.', 'Marking a transformative era in school education, the Hon\'ble Governor of Kerala Shri Arif Mohammed Khan formally dedicated MGM\'s Innovation Centre to the student community. The hub features humanoid robot OMNIS, Cubelets programmable blocks, VR astronomical learning simulations, and 3D printing equipment.', 'assets/images/Untitled-design-16.jpg', NULL, '1', '1', '4', '2026-10-24 15:15:06', '2026-10-24 15:15:06'),
('5', 'Annual Inter-House Sports Championship & Aquatic Meet 2025–26', 'annual-sports-championship-aquatic-meet', 'Sports', 'warning', '2026-08-05', 'August 05, 2026', 'The Annual Athletics and Aquatic Sports meet schedule has been declared. Competitions in swimming, track events, and team games across all four houses.', 'The Sports Department of MGM Model School has announced the itinerary for the Annual Inter-House Sports Championship and Swimming Competition. Events will take place at the campus athletic grounds and semi-olympic swimming facility. Parents and guardians are cordially invited to cheer the young champions.', 'assets/images/swimming-pool-facility-1.jpeg', NULL, '1', '1', '5', '2026-10-24 15:15:06', '2026-10-24 15:15:06'),
('6', 'Official Circular: School Working Hours, Transit Corridors & Visitor Policy', 'school-hours-transit-visitor-protocol', 'Circular', 'secondary', '2026-07-25', 'July 25, 2026', 'Important guidelines regarding campus gate timings, bus transport route schedules, student uniform standards, and prior appointment protocol for administrative desk meetings.', 'All parents and guardians are requested to take note of the campus operating guidelines. Classes operate Monday through Friday from 8:30 AM to 3:30 PM. Administrative counters function from 8:30 AM to 4:00 PM. Visitors must sign in at the security gateway and schedule appointments with faculty desks in advance.', 'assets/images/Untitled-design-4.png', NULL, '1', '1', '6', '2026-10-24 15:15:06', '2026-10-24 15:15:06'),
('7', 'Voice of MGM Cultural Fest & Inter-School Performing Arts Showcase', 'voice-of-mgm-cultural-fest', 'Celebration', 'primary', '2026-07-10', 'July 10, 2026', 'Celebrating creative arts, classical dance, music, elocution, and theatrical talents at the annual Voice of MGM youth festival.', 'The Voice of MGM Cultural Festival brings together students across grades to showcase their artistic flair in Indian classical dance, Western choir, mono-act, debate, painting, and mime. Certificates and trophies will be awarded during the valedictory session.', 'assets/images/scouts-and-guides.jpeg', NULL, '1', '1', '7', '2026-10-24 15:15:06', '2026-10-24 15:15:06');
